import { Heart, Shield, Clock, Home } from 'lucide-react';
import { SectionTitle } from '@/components/ui';
import type { HomePage, Benefit } from '@/types';

interface AboutSectionProps {
  aboutTitle?: string;
  aboutText?: string;
  benefits?: Benefit[];
}

const iconMap: Record<string, React.ReactNode> = {
  heart: <Heart size={24} color="var(--color-primary)" strokeWidth={2} />,
  shield: <Shield size={24} color="var(--color-primary)" strokeWidth={2} />,
  clock: <Clock size={24} color="var(--color-primary)" strokeWidth={2} />,
  home: <Home size={24} color="var(--color-primary)" strokeWidth={2} />,
};

const defaultBenefits: Benefit[] = [
  { id: 1, icon: 'heart', title: 'Atención humanizada', description: 'Tratamos a cada paciente con la calidez y respeto que merece, reconociendo su individualidad.' },
  { id: 2, icon: 'shield', title: 'Profesionales certificados', description: 'Todo nuestro equipo cuenta con titulación oficial y experiencia clínica comprobada.' },
  { id: 3, icon: 'clock', title: 'Disponibilidad continua', description: 'Estamos disponibles cuando más nos necesita, incluyendo fines de semana y festivos.' },
  { id: 4, icon: 'home', title: 'Cuidado en casa', description: 'El paciente se recupera mejor en su entorno familiar, con la comodidad de su hogar.' },
];

export function AboutSection({ aboutTitle, aboutText, benefits }: AboutSectionProps) {
  const displayBenefits = (benefits && benefits.length > 0) ? benefits : defaultBenefits;

  return (
    <section className="section" style={{ background: 'var(--color-off-white)' }} id="nosotros">
      <div className="container">
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
            gap: '4rem',
            alignItems: 'start',
          }}
        >
          {/* Left: About text */}
          <div>
            <span
              style={{
                display: 'inline-block',
                padding: '0.25rem 0.75rem',
                background: 'var(--color-primary-light)',
                color: 'var(--color-primary)',
                borderRadius: 'var(--radius-full)',
                fontSize: '0.8rem',
                fontWeight: 600,
                letterSpacing: '0.05em',
                textTransform: 'uppercase',
                marginBottom: '1rem',
              }}
            >
              Quiénes somos
            </span>
            <h2 style={{ marginBottom: '1.25rem' }}>
              {aboutTitle || 'Un equipo comprometido con su bienestar'}
            </h2>
            <p style={{ fontSize: '1.05rem', lineHeight: 1.8, marginBottom: '1.5rem' }}>
              {aboutText ||
                'Somos un equipo de enfermeras y técnicos en enfermería con más de 10 años de experiencia en cuidado domiciliario. Nos especializamos en brindar atención de calidad, humana y comprometida, directamente en el hogar de nuestros pacientes.'}
            </p>
            <p style={{ lineHeight: 1.8, color: 'var(--color-gray-500)' }}>
              Entendemos que cada persona es única, por eso diseñamos planes de cuidado personalizados que respetan la dignidad y bienestar de quienes cuidamos, siempre coordinados con la familia y el equipo médico.
            </p>

            {/* Stats */}
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(3, 1fr)',
                gap: '1rem',
                marginTop: '2rem',
              }}
            >
              {[
                { value: '+10', label: 'Años de experiencia' },
                { value: '+500', label: 'Pacientes atendidos' },
                { value: '100%', label: 'Profesionales certificados' },
              ].map(({ value, label }) => (
                <div
                  key={label}
                  style={{
                    textAlign: 'center',
                    padding: '1rem',
                    background: 'var(--color-white)',
                    borderRadius: 'var(--radius-md)',
                    boxShadow: 'var(--shadow-sm)',
                  }}
                >
                  <div
                    style={{
                      fontFamily: 'var(--font-heading)',
                      fontSize: '1.5rem',
                      fontWeight: 700,
                      color: 'var(--color-primary)',
                    }}
                  >
                    {value}
                  </div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--color-gray-500)', lineHeight: 1.3 }}>
                    {label}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Right: Benefits grid */}
          <div>
            <h3 style={{ marginBottom: '1.5rem', color: 'var(--color-gray-700)', fontSize: '1.1rem' }}>
              ¿Por qué elegirnos?
            </h3>
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
                gap: '1rem',
              }}
            >
              {displayBenefits.map((benefit) => (
                <div
                  key={benefit.id}
                  style={{
                    background: 'var(--color-white)',
                    borderRadius: 'var(--radius-md)',
                    padding: '1.5rem',
                    boxShadow: 'var(--shadow-sm)',
                    border: '1px solid var(--color-gray-100)',
                    transition: 'var(--transition-slow)',
                  }}
                  className="benefit-card"
                >
                  <div
                    style={{
                      width: '44px',
                      height: '44px',
                      background: 'var(--color-primary-light)',
                      borderRadius: 'var(--radius-sm)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      marginBottom: '1rem',
                    }}
                    aria-hidden="true"
                  >
                    {iconMap[benefit.icon] || iconMap.heart}
                  </div>
                  <h4 style={{ marginBottom: '0.5rem', fontSize: '1rem', color: 'var(--color-gray-900)' }}>
                    {benefit.title}
                  </h4>
                  <p style={{ fontSize: '0.9rem', lineHeight: 1.6, color: 'var(--color-gray-500)' }}>
                    {benefit.description}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .benefit-card:hover {
          box-shadow: var(--shadow-md) !important;
          border-color: var(--color-primary-light) !important;
        }
      `}</style>
    </section>
  );
}
