import type { Metadata } from 'next';
import { HeroSection } from '@/components/sections/HeroSection';
import { AboutSection } from '@/components/sections/AboutSection';
import { ServicesPreview } from '@/components/sections/ServicesSection';
import { TestimonialsSection } from '@/components/sections/TestimonialsSection';
import { CTASection } from '@/components/sections/CTASection';
import {
  getHomePage,
  getServices,
  getTestimonials,
  getContactInfo,
} from '@/lib/strapi';
import {
  fallbackHomePage,
  fallbackServices,
  fallbackTestimonials,
  fallbackContactInfo,
} from '@/lib/fallback-data';

export async function generateMetadata(): Promise<Metadata> {
  const home = await getHomePage();
  const data = home || fallbackHomePage;

  return {
    title: data.seoTitle || 'CuidadoEnfermería | Servicios de Enfermería Domiciliaria',
    description:
      data.seoDescription ||
      'Servicios profesionales de enfermería domiciliaria. Cuidado de adultos mayores, postoperatorio, administración de medicamentos. Profesionales certificados.',
    openGraph: {
      title: data.seoTitle || 'CuidadoEnfermería',
      description: data.seoDescription || '',
    },
  };
}

export default async function HomePage() {
  const [homeData, services, testimonials, contactInfo] = await Promise.all([
    getHomePage(),
    getServices(true), // featured only for preview
    getTestimonials(),
    getContactInfo(),
  ]);

  const home = homeData || fallbackHomePage;
  const displayServices = services.length > 0 ? services : fallbackServices.slice(0, 3);
  const displayTestimonials = testimonials.length > 0 ? testimonials : fallbackTestimonials;
  const contactInfoData = contactInfo || fallbackContactInfo;

  return (
    <>
      <HeroSection data={home} />
      <AboutSection
        aboutTitle={home.aboutTitle}
        aboutText={home.aboutText}
        benefits={home.benefits}
      />
      <ServicesPreview services={displayServices} />
      <TestimonialsSection testimonials={displayTestimonials} />
      <CTASection
        title={home.finalCtaTitle}
        text={home.finalCtaText}
        phone={contactInfoData.phone}
      />
    </>
  );
}
